      fills("sv"), fills("rvkn"), fills("rvks"),
      edge("sv", INK, 2.2), edge("rvk", INK, 2.2), edge("rvkn", INK, 2.2), edge("rvks", INK, 2.2),
      selected ? edge(selected, RUST, 3.2) : null
